#!/bin/bash
# Auto-generated by /create-mvp-spec for rn-shipyard
# Checks that all required tools are installed before building

ERRORS=0

echo "rn-shipyard Preflight Check"
echo "================================"
echo ""

# Check Node.js
if command -v node &> /dev/null; then
    NODE_VERSION=$(node -v)
    echo "  Node.js: $NODE_VERSION"
else
    echo "  Node.js: not found (install: brew install node)"
    ERRORS=$((ERRORS+1))
fi

# Check Ruby
if command -v ruby &> /dev/null; then
    RUBY_VERSION=$(ruby -v | cut -d' ' -f2)
    echo "  Ruby: $RUBY_VERSION"
else
    echo "  Ruby: not found (install: brew install ruby)"
    ERRORS=$((ERRORS+1))
fi

# Check Fastlane
if command -v fastlane &> /dev/null; then
    FL_VERSION=$(fastlane --version 2>&1 | tail -1 | tr -d '[:space:]')
    echo "  Fastlane: installed"
else
    echo "  Fastlane: not found (install: gem install fastlane)"
    ERRORS=$((ERRORS+1))
fi

# Check Xcode
if command -v xcodebuild &> /dev/null; then
    XCODE_VERSION=$(xcodebuild -version 2>&1 | head -1)
    echo "  Xcode: $XCODE_VERSION"
else
    echo "  Xcode: not found (install from Mac App Store + xcode-select --install)"
    ERRORS=$((ERRORS+1))
fi

# Check CocoaPods
if command -v pod &> /dev/null; then
    POD_VERSION=$(pod --version)
    echo "  CocoaPods: $POD_VERSION"
else
    echo "  CocoaPods: not found (install: gem install cocoapods)"
    ERRORS=$((ERRORS+1))
fi

# Check Android SDK
if [ -n "$ANDROID_HOME" ] && [ -d "$ANDROID_HOME" ]; then
    echo "  Android SDK: $ANDROID_HOME"
else
    echo "  Android SDK: ANDROID_HOME not set (install Android Studio)"
    ERRORS=$((ERRORS+1))
fi

# Check JDK
if command -v java &> /dev/null; then
    JAVA_VERSION=$(java -version 2>&1 | head -1)
    echo "  JDK: $JAVA_VERSION"
else
    echo "  JDK: not found (install: brew install openjdk)"
    ERRORS=$((ERRORS+1))
fi

# Check keytool
if command -v keytool &> /dev/null; then
    echo "  keytool: available"
else
    echo "  keytool: not found (part of JDK)"
    ERRORS=$((ERRORS+1))
fi

# Check Expo CLI
if npx expo --version &> /dev/null; then
    EXPO_VERSION=$(npx expo --version 2>&1)
    echo "  Expo CLI: $EXPO_VERSION"
else
    echo "  Expo CLI: not found (install: npm install -g expo)"
    ERRORS=$((ERRORS+1))
fi

echo ""
echo "================================"
if [ $ERRORS -gt 0 ]; then
    echo "$ERRORS preflight checks failed. Fix before building."
    exit 1
else
    echo "All preflight checks passed. Ready to build."
    exit 0
fi
